// Array initialization
// A: i x j
// r: i
// p: j
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Hoist lengths out of the traversals to avoid recomputing them
	const std::size_t m = p | get_length<'j'>();
	const std::size_t n = r | get_length<'i'>();

	// p[j] = (j % m) / m;
	// Since j is in [0, m), j % m == j exactly, so we can drop the modulo.
	traverser(p).for_each([&](auto state) {
		auto j = get_index<'j'>(state);
		p[state] = static_cast<num_t>(j) / static_cast<num_t>(m);
	});

	// r[i] = (i % n) / n;
	// Similarly, i is in [0, n), so i % n == i exactly.
	traverser(r).for_each([&](auto state) {
		auto i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(i) / static_cast<num_t>(n);
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// We keep the modulo here, as i*(j+1) may be >= n.
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = static_cast<num_t>((i * (j + 1)) % n) / static_cast<num_t>(n);
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// Optimization notes:
//  * s[j] is still accumulated in-place, as in the original code.
//  * For each i, we keep q[i] in a scalar accumulator (qi) and write it
//    back once after the inner j loop, instead of updating q[i] on every
//    j-iteration. This removes N*M loads/stores of q and improves
//    vectorization opportunities.
//  * r[i] is loaded once per i (into ri) instead of via r[state] in the
//    inner loop.
//  * A[i][j] is loaded once per (i,j) into Aij and reused for both updates.
