		auto istate = inner.state();

		// Load r[i] once and keep q[i] in a register accumulator
		const num_t ri = r[istate];
		num_t qi = SCALAR_VAL(0.0);

		// Loop over j
		inner.for_each([&](auto state) {
			// state has 'i' and 'j'
			const num_t Aij = A[state];
			const num_t pj  = p[state];

			// s[j] += r[i] * A[i][j];
			// r[i] is taken from ri, avoiding an extra indexed load.
			s[state] += ri * Aij;

			// Accumulate q[i] in a scalar
			qi += Aij * pj;
		});

