#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "bicg.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j (row-major: j is the inner/fast dimension)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// 1D vectors
	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// Array initialization
// A: i x j
// r: i
// p: j
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Pre-compute lengths and their reciprocals once to avoid repeated queries/divisions
	const std::size_t n = A | get_length<'i'>();
	const std::size_t m = A | get_length<'j'>();

	const num_t inv_n = SCALAR_VAL(1.0) / static_cast<num_t>(n);
	const num_t inv_m = SCALAR_VAL(1.0) / static_cast<num_t>(m);

	// p[j] = (j % m) / m;
	traverser(p).for_each([=](auto state) {
		const auto j = get_index<'j'>(state);
		p[state] = static_cast<num_t>(j % m) * inv_m;
	});

	// r[i] = (i % n) / n;
	traverser(r).for_each([=](auto state) {
		const auto i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(i % n) * inv_n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	traverser(A).for_each([=](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = static_cast<num_t>((i * (j + 1)) % n) * inv_n;
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// q[i] = 0 for all i
	// Explicitly zero q outside the inner computation loop so that:
	//  - we avoid needless loads/stores inside the hot j-loop
	//  - q is correctly initialized even when N == 0
	traverser(q).for_each([&](auto state) {
		q[state] = SCALAR_VAL(0.0);
	});

	// For each i:
	//   for each j:
	//     s[j] += r[i] * A[i][j];
	//     q[i] += A[i][j] * p[j];
	//
	// We iterate over rows of A (dimension 'i') first so that the inner
	// j-loop walks A, s and p contiguously in memory (j is the fast dim).
	noarr::traverser(A).template for_dims<'i'>([&](auto row_trav) {
		// State with current i fixed
		auto istate = row_trav.state();

		// r[i] is reused across the whole row, so load it once
		const num_t r_i = r[istate];

		// Accumulator kept in a register; stored back to q[i] after j-loop
		num_t q_i = SCALAR_VAL(0.0);

		// Loop over all j for this fixed i
		row_trav.for_each([&](auto state) {
			// state has 'i' and 'j'
			const num_t a_ij = A[state];  // A[i][j]
			const num_t p_j  = p[state];  // p[j] (ignores 'i')

			// s[j] += r[i] * A[i][j];
			// s uses only 'j', but we can reuse the same state; 'i' is ignored
			s[state] += r_i * a_ij;

			// q[i] += A[i][j] * p[j];
			// q uses only 'i', so we accumulate into the scalar q_i
			q_i += a_ij * p_j;
		});

		// Store the accumulated q[i]
		q[istate] = q_i;
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Retrieve problem size
	std::size_t n = N; // length in 'i'
	std::size_t m = M; // length in 'j'

	// Common length proto-structure
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(m);

	// Allocate bags with chosen layouts
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto s = noarr::bag(noarr::scalar<num_t>() ^ tuning.s_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);

	// Initialize arrays
	init_array(A.get_ref(), r.get_ref(), p.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_bicg(A.get_ref(), s.get_ref(), q.get_ref(), p.get_ref(), r.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print live-out data to prevent dead-code elimination
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, s.get_ref());
		noarr::serialize_data(std::cerr, q.get_ref());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
